/* Evolvlings: English text for the era 2 path conversations (parallel to events-era2.js). */
window.EVEVENTS_EN = window.EVEVENTS_EN || {};
(function (E) {
  const add = (zone, evs) => { E[zone] = Object.assign(E[zone] || {}, evs); };

  add("aurora", {
    "e2-ley": { who: { cirio: "Cirio, notice-board warden", umbria: "Umbría" }, nodes: {
      a: { say: ["The Ford's notice board has a new paper, nailed up with four nails instead of one. A young warden guards it with his arms crossed. At the top, in big letters: THE LAW OF RETURN.",
                 "Read it out loud if you like, nobody else comes near it today. My name's Cirio, and I'm to look after it until the ink dries.",
                 "Behind you, a Shadow woman holding two children by the hand waits for you to step aside so she can read it herself."],
           opts: ["Read the decree", "“What happens if someone doesn't go back?”", "Talk to the woman with the children", "Sign as a witness, as the foot of the paper asks", "Tear the decree off the board", "Leave without a word"] },
      leer: { say: ["“The Underside is cured. The families of the Night will return to their lands before the first frost. The Seven Houses will pay for the journey. Whoever does not return will lose their Threshold permit.”",
                    "At the foot, a line for witnesses. Forty signatures already. Nearly all of them from Meadow folk.",
                    "They say there's no sap down there anymore. That it's all clean. I've never been down, but the Houses say so."] },
      si: { say: ["They lose the permit. No permit, no crossing the Threshold, and no crossing, no work in the Meadow.",
                  "It isn't cruelty, Caretaker. It's that we don't fit here anymore. My sister's been sleeping in the kitchen since they gave her room to a family from the Hollow.",
                  "He says it without looking at the woman with the children, who hears every word."] },
      madre: { say: ["My name is Umbría. Don't mind the warden, he's not a bad man. He just repeats.",
                     "My husband went down to see the Hollow last week. He says it's clean, yes. And that the mist doesn't breathe. That the houses cast no shade. That he touched the wall of ours and it was warm, like an animal that died not long ago.",
                     "The children were born up here. For them the Underside is a story. How do you go back to a story?"],
               opts: ["“You can stay at my house in the Ford.”", "“What do you need for the journey?”", "Go back to the board"] },
      viaje: { say: ["Nothing you have. The Houses pay for the cart, the blanket and three days of bread. Very generous.",
                     "What they don't pay for is the way back, if you can't live down there. That's not on the paper."] },
      firmar: { say: ["You sign below the other forty. Cirio blows on the ink very carefully, as if it mattered that it didn't run.",
                      "Thank you. When a Caretaker signs, people believe it more.",
                      "When you turn around, Umbría has already gone with the children. In the mud, the prints of all three lead towards the gate."] },
      arrancar: { say: ["You pull at the paper. The four nails hold and the decree tears down the middle, with a sound the whole square hears.",
                        "What are you doing? The matriarch signed that!",
                        "Cirio calls the wardens. Tomorrow there'll be another paper, with eight nails. But today the board holds only the bottom half: forty signatures with nothing above them."] },
      esconder: { say: ["Umbría looks at you for a long time. Then she says something to the children in the Court's tongue, and the smallest hides behind her.",
                        "I won't thank you yet. First let's see whether the Houses come looking for us.",
                        "But if they don't, the Quarter will hear that in the Ford there's a door that opens. And that, Caretaker, is worth more than your house."] },
      irte: { say: ["A while later, from far off, you see Umbría reading the paper with one finger, word by word, while the smallest tugs at her skirt."] },
    } },

    "e2-coro": { who: { nim: "Nim", tila: "Tila", capataz: "Choir mistress" }, nodes: {
      a: { say: ["In the Dark Quarter they've built a stage under the last lantern. On it, in pairs, Light children and Shadow children sing in turns. A choir mistress beats time with a rod. Each time a pair finishes, the lantern shines a little brighter.",
                 "Together! Both lullabies at once, like in the Ford! The matriarch wants light for the whole Quarter before winter.",
                 "In the third pair, singing with a Light girl he doesn't know, is Nim. He sings well. He looks at no one."],
           opts: ["Listen to how it sounds", "Look for Tila in the crowd", "Get up on the stage and sing with them", "Sing off-key on purpose, very loudly", "Wait for Nim to come down and take him away"] },
      suena: { say: ["It sounds pretty and it sounds like nothing. The two lullabies go together, note for note, but every child looks the other way. The sap doesn't pull back an inch.",
                     "At the foot of the stage, on a rag, lie three little bright things the size of a fist. They're Stars. They make no sound. One has already gone out completely.",
                     "They come out on their own, sometimes. They're no use. They go out in two or three days."] },
      tila: { say: ["Here I am, watching them copy me. When Nim and I did it, it was because we wanted to. This is a line of kids paid half a ration to sing.",
                    "I told the matriarch. She said I was the proof that it worked. That thanks to me the Quarter would have light. And the worst part is she meant it.",
                    "Look at those Stars. That's what a promise nobody wanted to make sounds like."] },
      cantar: { say: ["The mistress puts you beside a Shadow boy who's trembling a little. You sing. The lantern shines. Everyone claps.",
                      "A new Star falls at your feet, the size of a walnut. It looks at you without a mouth. It shines three seconds longer than the others and goes still.",
                      "Come back tomorrow! With a Caretaker on the stage, the Quarter sings twice as much."] },
      sabotear: { say: ["You push in among the pairs and sing loud and badly. One pair laughs, another stops. The mistress strikes the stage with her rod.",
                        "Out! Wardens!",
                        "Nim uses the commotion to get off the stage. Passing you, without looking, he says very quietly: “Thanks. I'll be back tomorrow anyway. It pays.”"] },
      sacar: { say: ["When Nim's pair finishes, you wait for him at the foot of the stage. He's pale, as if he'd sung with someone else's throat.",
                     "Don't take me out of here like a child, I'm not one. I sing because my mother eats from what they pay me.",
                     "But if you really want to help, take that.",
                     "He points at the smallest Star on the rag, the one that still glows a little. Unísona looks at it and sings a single note. The Star moves."],
               opts: ["Take the Star", "Take Nim, even if he protests"] },
      estrella: { say: ["You wrap it in your scarf. It weighs nothing. Unísona walks beside you all the way back, watching it, the way you watch a sick little brother.",
                        "Give it a name. The ones with names find it harder to go out. My mother used to say that about children, and I think it goes for everything."] },
      nimlejos: { say: ["If you take me, tomorrow they'll put someone else up. Someone smaller, who sings worse and gets paid less.",
                        "But he comes down with you. At the Quarter's door he stops, looks at the stage and sings alone, softly, his whole lullaby. Nobody pays him. The lantern doesn't shine any brighter.",
                        "That one was for me."] },
    } },

    "e2-velada": { who: { destello: "Lucerna Destello", alvar: "Alvar" }, nodes: {
      a: { say: ["It's the longest night of the year. Every House in the Meadow lights all its lanterns at once. The sky turns white. There's music, sweet bread and people dancing in the squares.",
                 "On the balcony of the Tower of Dawn, a young woman with her hair tied back and a plain dress waves to the crowd. She wears no jewels. The Quarter folk cheer her louder than anyone.",
                 "That's the new matriarch. Lucerna Destello. She was born in the Dark Quarter, did you know? The first one who isn't from an old House.",
                 "Alvar has grown. His boots are caked in mud and he doesn't seem to mind."],
           opts: ["“And your grandmother?”", "Look at the ground of the square", "Climb to the balcony to talk to the matriarch", "Break the big lantern in the square", "Dance with the crowd"] },
      abuela: { say: ["They pushed her aside. Because of the tubes, they say. She says she deserved it, and then spends the afternoon giving orders to the flowerpots.",
                      "She didn't come today. She said a Vigil with every lantern lit frightened her. That her grandmother told her something about a debt you don't pay to the sun. I didn't understand."] },
      suelo: { say: ["Between the stones of the square, in the cracks, there's something dark. At first it looks like shadow. Then you see it moving, slowly, like water rising.",
                     "You crouch down. It smells of wet earth and of something sweet and rotten. Under the feet of the dancers, the clear sap is turning black."] },
      balcon: { say: ["The Caretaker. Come in, come in, tonight the Tower belongs to everyone.",
                      "See that? A year ago, on my street, one lantern in three was lit. Tonight there isn't a single dark door in the Quarter. We did that, not Albor."],
                opts: ["“The sap is rising through the square.”", "“Where does so much light come from?”", "“Congratulations.”"] },
      donde: { say: ["From below, as always. The difference is that now it reaches everyone.",
                     "I know what you're going to say, Caretaker. That Albor drank from the Root. I know. That's why we dig deeper, where it bothers nobody. My engineers checked."] },
      aviso: { say: ["Destello looks down at the square. For a moment her smile fades. Then it comes back.",
                     "It's the shadow of so many people dancing. Not tonight, Caretaker. Tonight the Quarter has light. Tomorrow we look at the ground, I promise.",
                     "I saw it too. If you want, tomorrow I'll tell the old Houses. They still open the door to me."],
               opts: ["“Do it, Alvar. Let every House know.”", "Leave it for tomorrow"] },
      alvarsi: { say: ["First thing tomorrow. Even if they throw me out. I've been thrown out of worse.",
                       "Below, without anyone else noticing, the last crack in the square turns black."] },
      manana: { say: ["The next morning, the Meadow wakes to black stains in every square. The Houses say it was Shadow sabotage."] },
      felicidades: { say: ["Thank you. Really. You're one of the few who says it without asking me for something in return.",
                           "From the balcony, the square looks beautiful. From up here you can't see the ground."] },
      romper: { say: ["You throw a stone at the big lantern. The glass cracks and the light flickers. The music stops. Someone shouts “shadows!” and people draw back from the Quarter folk.",
                      "That's not what you wanted. But in the dark of the broken lantern, under your feet, the ground stops darkening. A hand's breadth. Just a hand's breadth."] },
      bailar: { say: ["You dance until your feet hurt. Your creatures too. It's the best party in years. Nobody looks at the ground, and neither do you."] },
    } },
  });

  add("crater", {
    "e2-tubos": { who: { tizon: "Master Tizón", fogarin: "Fogarín" }, nodes: {
      a: { say: ["In the great forge there are glass tubes everywhere, leaning against the walls like spears. They're three times longer than the ones that left here last year.",
                 "Don't touch them, they're still warm. An order from the new matriarch. Two hundred. Pays in advance, can you believe it? In advance. Albor never paid in advance.",
                 "At the back, a young man with old burns on his arms works the bellows without a word. It's Fogarín, the apprentice. Not so much an apprentice anymore."],
           opts: ["“Why are they so long?”", "Talk to Fogarín", "“Master, these tubes drink from the Root.”", "Break one “by accident”", "Help load the order"] },
      para: { say: ["To reach deeper, she says. Where they won't bother anyone. I didn't ask more. I've had a seat on the Council of Houses for a month, and a Fire with a seat learns fast which questions aren't asked.",
                    "They used to keep me out of the front door. Now they serve me first. Don't ask me to throw that away on a hunch."] },
      fogarin: { say: ["I blow, I don't give opinions. That's what the master taught me.",
                       "But I'll tell you one thing. When a girl from the Water worked here, she told me long glass sings when you cool it. This one doesn't sing. This one sounds like someone swallowing."] },
      decir: { say: ["And who says so? A lake seer? A shadow?",
                     "But he sets the hammer down on the anvil. For a long time.",
                     "My father kept the Night of Embers. He put out every fire in the Crater and lit just one, one night a year. He said it was so the earth could rest. We laughed at him."],
              opts: ["“Keep the Night of Embers this year.”", "“Come to the Heart when I call.”", "Don't press him"] },
      ascuas: { say: ["Put out the Crater for a night, with two hundred tubes to deliver? They'd throw me off the Council before dawn.",
                      "But look, I can deliver a hundred and ninety. Ten break. Happens in every forge. Nobody counts broken glass."] },
      corazon: { say: ["You paid me in full when nobody did. I don't forget that.",
                       "If one day something rings out at the Heart and the Fire has to be there, the Fire will be there. Even if it's just me, with my hammer and my bad knees."] },
      romper: { say: ["You lean where you shouldn't. A tube falls and shatters. Tizón looks at you, red in the face.",
                      "I'm docking that from what I'll never pay you. Out of my forge.",
                      "On your way out, Fogarín catches up and presses a shard of glass into your hand. Inside it runs a black vein, thin as a hair."] },
      cargar: { say: ["You load tubes all afternoon. Tizón pays you in new coins, stamped with Destello's seal. They weigh more than Albor's."] },
    } },

    "e2-brida": { who: { brida: "Brida, forewoman" }, nodes: {
      a: { say: ["In the baths square, a Shadow woman in a miner's helmet writes names on a board. A line of Crater workers waits their turn. The board says: DIGGERS WANTED. DOUBLE PAY. NO ONE ASKS WHERE YOU'RE FROM.",
                 "Here to work? You've got working hands. Here everyone has a name, Caretaker. Mine's Brida. I earned it."],
           opts: ["“How do you earn a name?”", "“Where's the digging?”", "Put your name on the board", "Warn the people in line about what's down there", "“I'm offering you other work, in the Ford.”"] },
      nombre: { say: ["By working. When we came up from the Hollow, they called us Court folk “the dusty one”, “the one in the third row”. In Albor's Wells nobody said our names, and neither did we: the King forbade it.",
                      "The new matriarch asked me what my name was. The first person from up here who ever asked. I told her one I'd made up that same morning. She wrote it down as if it were real.",
                      "For that woman I'd dig to the bottom of the world."] },
      donde: { say: ["Under the Meadow, deeper than Albor. New wells. They call them blind because they have no mouth up top: you get in through tunnels from far away, so nobody sees them.",
                     "Why so hidden? So nobody sabotages them. Someone already broke lanterns at the Vigil."] },
      apuntar: { say: ["Good. Tomorrow at the ash hour, at the mouth of the south tunnel. Bring water. It's strangely hot down there, like an animal.",
                       "She gives you a wooden token with a number. Yours is 312."] },
      avisar: { say: ["You climb onto the edge of a fountain and tell them what you know about the Wells and the Root. A few people leave the line. Most stay: the pay is double.",
                      "Very nice. Now explain to their children why they won't eat this week.",
                      "She doesn't shout. She looks at you with her helmet in her hand, the way you look at someone who understood nothing."] },
      otro: { say: ["In the Ford? Looking after what, creatures? How much does that pay?",
                    "I heard you're hiding a Court family. Umbría. I know her: we were neighbours in the Wells. She refused to take a false name.",
                    "Brida goes quiet. She crosses something out on the board. You can't see what.",
                    "I'm not leaving the Wells. But if something happens down there one day, I'll warn you before the matriarch. That much I can do."] },
    } },
  });

  add("forest", {
    "e2-fruta": { who: { liquen: "Grandpa Liquen", llovizna: "Llovizna" }, nodes: {
      a: { say: ["The branches of the Deep Wood bend with fruit. Apples, acorns, blackberries, all at once and out of season. There's so much on the ground that the path smells of wine.",
                 "Caretaker! Look how many! The Council says it's the Clear Sap, that the Root is giving back what we took from it.",
                 "A little further on, sitting on a root, Grandpa Liquen stares at a heavily laden apple tree. He isn't eating."],
           opts: ["Help Llovizna gather fruit", "Sit with the old man", "Cut a branch to see what's inside", "“Grandpa, we have to call the Long Silence.”"] },
      juntar: { say: ["You fill two baskets. The apples are huge and sweet, too sweet. Your creatures eat until they fall asleep.",
                      "This year nobody goes hungry in the Wood!"] },
      liquen: { say: ["This year the wood has given more fruit than ever. That's what frightens me.",
                      "When I was a boy, in the Wood I came from, the same thing happened. An autumn of fruit like this one. The next winter there was nothing left. The trees had eaten the soil to make fruit, like a mother who goes without bread.",
                      "And the Hedge is withering out of season. Look. The thorns I planted to close the way fall off by themselves, with black flowers at the tips."] },
      rama: { say: ["You cut a branch from the apple tree. Outside it's green. Inside, in the heart of the wood, runs a thin black vein, like ink.",
                    "Llovizna covers her mouth. Liquen nods slowly, as if he already knew."] },
      silencio: { say: ["Now? In autumn? The Long Silence is in winter. If I call it early, the Council will say the old man from outside doesn't even know what season he's in.",
                        "Years ago, during a Long Silence, I heard it cough. I told no one. For fear they'd open the Vault. I kept it to myself, and look where we are."],
                  opts: ["“This time, don't keep it to yourself.”", "“Then listen to it on your own.”"] },
      llama: { say: ["Fine. Tomorrow I'll strike the hollow trunk. Let them laugh. The Wood will be quiet for three days, even with fruit rotting on the ground.",
                     "And if one day someone sings at the Heart and the Wood is needed, the Wood will be there. That promise I will keep."] },
      solo: { say: ["Liquen presses his ear to the apple tree. So do you. For a long while there's nothing to hear.",
                    "It isn't coughing. It's breathing deeply, very deeply, like someone sleeping hungry."] },
    } },

    "e2-seto": { who: { abrojo: "Abrojo, Hedge guard" }, nodes: {
      a: { say: ["Where the thorn Hedge used to be, there's now a dry brown wall. On the other side, on the road to the Underside, a line of Law of Return carts waits to be let through.",
                 "The Council sent me to cut a gap. The Houses pay for the displaced to go back this way, it's shorter.",
                 "The odd thing is the Hedge won't let me. I cut one branch and two grow back. Dry, but they grow. As if it didn't want anyone going back this way."],
           opts: ["Help Abrojo open the way", "Talk to the people in the carts", "Touch the Hedge", "Leave the Hedge closed"] },
      carros: { say: ["In the first cart rides an old man of the Tides with an old boat tied on top. There's no water on the road, but he wouldn't leave it.",
                      "“They say the lake is cured,” he tells you. “What I want to know is whether the lake will recognise me.”"] },
      tocar: { say: ["You put your hand on the dry wall. It's warm. Inside, very slowly, something beats. The Hedge's roots went deep, much deeper than Liquen meant, and down there they found something to drink.",
                     "The Hedge isn't a wall. It's an embrace that won't let go."] },
      abrir: { say: ["The two of you cut for hours. At last a gap opens as wide as a cart. The old man with the boat goes through first. He doesn't say thank you. He cries.",
                     "There. The Council will be pleased. The Houses too."] },
      cerrado: { say: ["If I don't open it, the Houses will send their wardens with axes, and they won't be careful with the Hedge.",
                       "But he puts the shears away. The carts turn around, towards the long road. They'll take three more days to reach a place that may not want them."] },
    } },
  });

  add("heights", {
    "e2-bajan": { who: { tormo: "Tormo, pass guard" }, nodes: {
      a: { say: ["Down the Heights road comes a line of people with blankets over their shoulders. Whole families, with kites folded on their backs like broken wings.",
                 "Forty families this week. Without the Lady of the Choir's dealings, nobody eats in the Heights this winter. They come down to the Meadow to beg.",
                 "Two winters ago I closed this pass so the people below couldn't come up. Now I open it so the people above can come down. With the same blanket."],
           opts: ["Share food among the families", "“Why did the dealings break down?”", "Show them the way to the Ford", "Keep climbing without stopping"] },
      tratos: { say: ["Because someone sang in the square that the exodus storm never happened. That the Lady lied to close the passes.",
                      "It was true. I was at the pass that week. Clear sky. But now nobody trusts the Choir, nobody sells anything to the Heights, and these are the ones who pay."] },
      comida: { say: ["You share bread and fruit from the Wood among the children. A girl with a red kite gives you a blue feather in return.",
                      "“So the wind can find you,” she says. It's what they say in the Heights when there's nothing else to give."] },
      vado: { say: ["You explain how to reach the Ford. Some of them exchange uneasy looks. “Is there no Law of Return there?” a man asks.",
                    "You don't know what to tell him."] },
      seguir: { say: ["You climb against the stream of people. Nobody asks you for anything. In the Heights you don't ask; you wait."] },
    } },

    "e2-cefira": { who: { cefira: "Céfira", arpegio: "Arpegio" }, nodes: {
      a: { say: ["In the Choir hall there are three chairs. One is empty. In another, a barefoot old man watches a woman's mouth to read her lips. The woman, in the third, says nothing. She hasn't said anything in public for a year.",
                 "You talk, she answers you. Me she only looks at now. Since the trial everyone knows I can't hear, and she can't stand that I know she knows."],
           opts: ["“Céfira, your people are coming down to beg.”", "“Why did you lie about the storm?”", "Speak to her with your hands, as Arpegio does", "Leave her in peace"] },
      mintio: { say: ["Because there wasn't food for everyone. If I let the second wave come up, the Heights would eat half for one winter, and the next one nobody would eat.",
                      "I closed the passes and said “storm”, which is easier to forgive than “there's no room”. People died below. I know. I count them every night.",
                      "It's the first thing she's said in a year. Arpegio leans forward to read it."] },
      pueblo: { say: ["I know. I see them from the window. My silence is all they have left: if I speak, the Meadow hears the liar of the exodus, and they close the door on them too."],
                opts: ["“Speak in the square. Tell the truth, and ask.”", "“Then stay silent.”"] },
      manos: { say: ["You make with your hands the little you learned from Arpegio: “I”, “listen”, “you”. Céfira laughs for the first time, a short, broken laugh.",
                     "You told her “I listen to you”. Nobody in the Choir has said that to her in forty years."] },
      plaza: { say: ["Ask? The Heights never ask. We share verses, we carry messages. We don't ask.",
                     "I can ask. They've already lost their respect for me. There's nothing to lose.",
                     "Céfira looks at the old man for a long time. Then she stands up.",
                     "I'll go down to the Meadow. I'll tell the truth and ask, the two of us together. And if the Heart ever calls the nine peoples, the Heights will go. This once, without selling anything."] },
      callada: { say: ["Céfira turns back to the window. Arpegio sighs and walks you to the door.",
                       "Keeping quiet is also a way of lying. I know that better than anyone."] },
      paz: { say: ["On your way out you hear Arpegio humming a song without sound. He knows the melody by heart. He never heard it."] },
    } },
  });

  add("hollow", {
    "e2-vuelta": { who: { calina: "Calina, mist weaver" }, nodes: {
      a: { say: ["The Hollow is clean. No sap in the cracks, no smell of fever. No mist either. The Court's houses, made for living in half-light, stand bare under a grey sky, like shorn animals.",
                 "We came back because of the Law. Twenty families. I've spent three days trying to weave mist and nothing comes. The Hollow doesn't breathe.",
                 "Calina's hands are full of grey threads that come apart when touched."],
           opts: ["“What does the mist need to come out?”", "Help her weave", "Sing the Shadow lullaby in the middle of the valley", "“Go back to the Meadow. This is no life.”"] },
      niebla: { say: ["It used to come out by itself, from the ground. The Root breathed below and the Hollow filled with its breath. We only combed it.",
                      "Now the Root sleeps so deep it doesn't breathe. They told us the Underside was cured. It's cured the way a dead man is cured: nothing hurts anymore."] },
      tejer: { say: ["You spend the afternoon with the threads. No mist comes, but by nightfall Calina manages a small veil, the size of a handkerchief, for her granddaughter's cradle.",
                     "It's not much. But it's the first thing we've made here since we came back."] },
      cantar: { say: ["In the middle of the valley you sing the lullaby Nim taught you. Unísona sings the other half with you, the Light half.",
                      "From the ground rises one strand of mist, just one, thin as a sigh. All twenty families come out of their houses to watch it. Nobody speaks until it fades.",
                      "It breathes. A little, but it breathes. If one day there's singing at the Heart, the Court has to be there. I'll see that we are."] },
      volver: { say: ["To the Meadow? Without a Threshold permit? We have no door up there anymore, Caretaker. The Law left us without a place on either side."] },
    } },

    "e2-nombres": { who: { ceniza: "Ceniza", lobrego: "King Lóbrego" }, nodes: {
      a: { say: ["In an empty house in the Hollow, behind a curtain, a Shadow girl hides with her hood pulled low. When she sees you, she shrinks back.",
                 "Don't say my name. They already said it in the Meadow square. The new matriarch shouted it, mine and two others, in front of everyone.",
                 "My name is Ceniza. That one you can know. The other, the real one, the whole Meadow knows now. For the Court, a shadow whose name has been spoken is a dead shadow."],
           opts: ["“Why did the matriarch do it?”", "“What happens to a named shadow?”", "Hide her in the Ford", "Take her before the king", "Leave and let her be"] },
      porque: { say: ["Because the king confessed the Wells pact on the Moonless Night. We shadows got our names back, and the borrowed quarter was over.",
                      "The matriarch got angry. She said that if the Court broke the deal, so would she. And she read out three names from a box Albor kept."] },
      pasa: { say: ["That anyone can call her. And the one called by her true name has to go. It isn't law, it's what we are.",
                    "Last night someone shouted my name under the window. Luckily he was drunk and got a letter wrong."] },
      vado: { say: ["Ceniza follows you to the Ford without speaking. At the door, she lowers her hood. Her face is very young and very tired.",
                    "Here nobody knows my real name. For now. Thank you, even if it doesn't last forever."] },
      rey: { say: ["In the largest tent, King Lóbrego receives you without his veil. It's the first time you've seen his face: an old man with sunken cheeks who no longer looks like a king.",
                   "Ceniza. I told you not to go out.",
                   "I confessed so my people could get their names back, Caretaker, and all I achieved was that three of them lost theirs for good. That's how fixes go. One pays and another collects."],
             opts: ["“What does the Court need?”", "“It was your fault.”"] },
      necesita: { say: ["A place where a name can't be shouted. And someone from above who sees us as something more than a debt.",
                        "If you call the peoples to the Heart, the Court will go. Veiled or unveiled. I have nothing left to hide."] },
      culpa: { say: ["It was. And yours too, and the matriarch's, and old Albor's, and everyone who drank from that light.",
                     "Ceniza stays with him. The king puts a hand on her shoulder, clumsily, like someone who never did it before."] },
      irte: { say: ["As you leave you hear someone, far off, shout a name you don't know. The curtain moves."] },
    } },
  });

  add("lake", {
    "e2-ciego": { who: { marejada: "Mother Marejada", orilla: "Orilla" }, nodes: {
      a: { say: ["The Mirror Lake no longer reflects. The water is clean and still, but when you lean over you see neither your face, nor the sky, nor anything. Only a smooth grey, like an eye with a cataract.",
                 "We came back because they told us the lake was cured. And it is. It has no sap. It has nothing. I've watched it for a week and it shows me neither tomorrow nor yesterday.",
                 "Beside her, Orilla reads her oilcloth notebook under her breath, turning old pages."],
           opts: ["“What happened to the lake?”", "Talk to Orilla", "Put your hand in the water", "“Mother, tell your people what you saw thirty years ago.”", "Leave them something to eat"] },
      paso: { say: ["The Root is asleep. The lake is the Root's eye: when it sees, the lake sees. Now its eyes are closed.",
                    "What nobody says is that a mother who sleeps like that doesn't wake to feed her children."] },
      orilla: { say: ["I'm looking in my mother's notebook to see whether this has happened before. Once. Long ago. The handwriting is very old, it isn't hers.",
                      "It says: “The lake did not reflect for three generations, until the Singer wept into it.” It doesn't say why she wept."] },
      mano: { say: ["The water is warm. When you pull your hand out, for a second a reflection that isn't yours stays in your palm: a woman with her mouth open, made of stone. Then it fades."] },
      contar: { say: ["They already know. Orilla told them. And since then half of them look at me as a liar and the other half as a coward.",
                      "But you're right about one thing. Whatever I don't tell, the lakeshore will tell when it dries.",
                      "That night, on the shore, Marejada speaks before all the Tides. She doesn't say much. She ends by asking forgiveness. Some leave. Most stay.",
                      "If one day we have to sing at the Heart, the Tides will go. Together, for the first time in thirty years."] },
      comer: { say: ["You leave them bread and fruit. Marejada accepts it without looking at you. “It isn't pride,” Orilla says. “It's that she finds it hard to accept things she didn't see coming.”"] },
    } },

    "e2-mudo": { who: { nasa: "Grandma Nasa" }, nodes: {
      a: { say: ["On the shore, among the beached boats, an old woman holds something wrapped in a fishing net. It glows a little. It's a Star the size of a fist, mouthless, still.",
                 "The water brought it this morning. From the Meadow, I'd say, that's where everything left over comes from. It makes no sound. It doesn't eat. It looks.",
                 "Unísona goes up to it on its own. The mouthless Star lifts its light a little, the way you lift your head."],
           opts: ["Let Unísona sing to it", "“How many like this one wash up?”", "Take it to the healer of the White Deep", "Leave it in the water"] },
      cuantas: { say: ["Three this week. The other two arrived already out. The children use them as stones to throw in the water. They don't skip.",
                       "In my day a Star was once in a lifetime, and there was a feast. Now they float on the shore like dead fish."] },
      unisona: { say: ["Unísona sings one long note and then falls silent, waiting. The Mute Star has no mouth to answer. But it glows in time, once, twice.",
                       "When Unísona stops, the Star keeps glowing. Brighter than before.",
                       "There you are. Now it has someone who listens to it. Take it with you. Give it a name."] },
      curandera: { say: ["You carry it in your pack as far as the road to the White Deep. When you take it out, it no longer glows.",
                         "Unísona doesn't sing the whole way back."] },
      agua: { say: ["You leave it in the water. It sinks slowly, glowing less and less. The lake, which reflects nothing, reflects that: a light going out."] },
    } },
  });

  add("caves", {
    "e2-noche": { who: { basalto: "First Pick Basalto", pirita: "Pirita, digger" }, nodes: {
      a: { say: ["It's the Night of the Echo. The families of the Hondura strike two stones at the entrance to the Hall, as the rite demands, and say their dead's names out loud. The cave always answered in their voice.",
                 "Tonight the cave doesn't answer. Strike, name, silence. Strike, name, silence.",
                 "Since they took the Guardian's verse, nobody answers. My father died last year and I haven't heard him once."],
           opts: ["Strike two stones yourself", "Talk to the First Pick", "Sing what Grava taught you", "Leave in silence"] },
      golpear: { say: ["You strike two stones. It sounds dry, with no echo. A Hondura child copies you, harder, as if it were a matter of strength."] },
      basalto: { say: ["Don't look at me like that. I know what you're thinking. I sold the maps. You took the verse. Between the two of us we left the Hondura without its dead.",
                       "The stone says it, and stone is the only thing that doesn't lie: those digging with my maps under the Meadow have already crossed the Line. I feel it in my hands, like a tremor."],
                 opts: ["“Come to the Heart when I call. We have to fix this together.”", "Go back to the entrance"] },
      juntos: { say: ["The Hondura never sings. We strike stones. If you call me, I'll come with two stones and the people behind me.",
                      "And I'll tell you something I've told no one. The Guardian repeated a verse that belonged to no people. I half remember it: “as long as no one drinks...”. I don't know the rest."] },
      grava: { say: ["You sing the first verses Grava sang with you. At first, nothing. Then, from very deep down, faintly, the cave repeats a word: “...drinks...”.",
                     "The families stand still. Pirita weeps without a sound.",
                     "It's her. She's still in there, somewhere. If one day the Hondura has to go to the Heart, we'll take her with us."] },
      irte: { say: ["Behind you the strikes go on. Strike, name, silence. All night."] },
    } },

    "e2-pozo": { who: { brida: "Brida, forewoman" }, nodes: {
      a: { say: ["Following a new tunnel, on no old Hondura map, you reach a huge chamber beneath the Meadow. In the centre a long glass tube, very long, runs down into a bottomless hole. It's a Blind Well.",
                 "The tube pulses. Light rises inside it, white and thick, towards the Meadow. All around, the rock sweats black sap.",
                 "You shouldn't be here. Nobody should be here. Not even me."],
           opts: ["“Brida, this is killing the Root.”", "Look into the hole", "Seal the well with the loose rock", "Take a piece of the tube to show in the square", "Leave it open: it's the Quarter's light"] },
      matando: { say: ["I know. I've known since last week, when my partner's hands turned black. Half the diggers know.",
                       "But if you close this, tomorrow the Dark Quarter is dark again. And the matriarch falls. And they take away the name she gave me."] },
      mirar: { say: ["You lean over. Far below, further down than anything should exist, something huge and dark stirs in its sleep. Every time the tube swallows, it flinches, like someone feeling cold.",
                     "Unísona covers its face with its paws. Its whole body is shaking."] },
      tapar: { say: ["You push loose rock against the mouth of the well. At first Brida just watches. Then she helps. It takes all night. The tube cracks, the light goes out, the pulse goes on.",
                     "Up there, a street in the Quarter just went dark. Tomorrow they'll ask me who did it.",
                     "I'll say it collapsed on its own. For once in my life I'll lie to her."] },
      denunciar: { say: ["You tear off a piece of tube, still hot, with black sap stuck to it. Brida doesn't stop you.",
                         "Show it. Let them see. But don't say you found it here, or tomorrow they hang the diggers and the matriarch stays as she is.",
                         "The next day, in the Meadow square, people look at the glass shard and murmur. Destello comes out on the balcony and says it's Shadow sabotage. Half the square believes her."] },
      abierto: { say: ["You turn away. Behind you the tube keeps pulsing, swallowing, sending up light for a thousand lanterns.",
                       "Thank you. I won't forget it. Neither will the Quarter.",
                       "Unísona doesn't follow you at once. It stays staring at the hole until you call it three times."] },
    } },
  });

  add("deep", {
    "e2-setas": { who: { esporina: "Esporina", yesca: "Yesca, grower" }, nodes: {
      a: { say: ["The mushroom fields of the White Deep are grey. The caps fall off by themselves, crumbled to dust. Since the sap cleared, the mushrooms that grew on it are dying.",
                 "They're the remedy ones. The ones that cured sap fever. Without them, the sick who'd recovered are falling ill again.",
                 "At the back, a woman with an enormous hat digs a hole in the ice with a shovel. She's already in it up to her waist."],
           opts: ["Talk to the woman with the shovel", "“How many sick have fallen ill again?”", "Help her dig", "“If you dig there, you'll wake it. Stop.”", "“Let's look for another remedy, without sap.”"] },
      cuantos: { say: ["Thirty in the Deep. In the Meadow I don't know, they don't count the Quarter folk up there.",
                       "The healer says the Heart's cure cured everyone except those who were already cured. I don't know if it's a joke."] },
      esporina: { say: ["Don't look at me like that, I'm not mad. Mushrooms grow where the sap is thick. The thickest left is down here, under the ice, where nobody put it fully to sleep.",
                        "You defended my remedies, remember? You got me permission to heal by day. Well, this is the price: to heal, I need the Root to stay a little sick."] },
      cavar: { say: ["You dig with her until the ice turns dark. Underneath, a vein of black sap, thick as honey. Esporina weeps with relief.",
                     "With this I can cure thirty. With a little more, the whole Quarter.",
                     "Beneath your feet, very deep, something turns over in its sleep."] },
      parar: { say: ["And what do I tell the thirty? To put up with it because the Caretaker is afraid of a root?",
                     "But she drops the shovel. She sits on the edge of the hole, feet dangling.",
                     "Fine. I'll stop. But when the first one dies, you'll be the one to tell their mother."] },
      otro: { say: ["A remedy without sap? I've been looking for one for twenty years.",
                    "Although... Grandpa Liquen says the Root breathes. If it breathes, it dreams. And if it dreams, maybe the dreamers of the Watch could... no, it's nonsense.",
                    "It isn't nonsense. She writes it inside her hat, in charcoal."] },
    } },

    "e2-oyen": { who: { nevisca: "Nevisca, dreamer of the Watch", albina: "Regent Albina" }, nodes: {
      a: { say: ["In the Watch hall, where the dreamers keep vigil over the Frozen Tomb, there are more people than ever. They sit in a circle with their eyes closed, repeating something under their breath, all at once.",
                 "The king has spoken again. For the first time in centuries, we truly hear him. Not like before, when they told us what to dream.",
                 "He says he's thirsty. That he wants to wake. We call ourselves Those Who Hear."],
           opts: ["Sit in the circle and listen", "“Who used to tell you what to dream?”", "Go and see the regent", "Join Those Who Hear"] },
      antes: { say: ["The regency. Everyone knows and nobody says: the Regent wrote the king's dreams and gave them to us to learn. I dreamed a dream she wrote for two years myself.",
                     "But nobody wrote this one. This one comes from below."] },
      escuchar: { say: ["You close your eyes. After a while, in the dark, you feel something enormous turning over, with a dry mouth, that doesn't remember why it promised to sleep.",
                        "You open your eyes with a dry throat. Nevisca smiles at you. Her lips are cracked, like everyone's in the circle."] },
      regente: { say: ["Those Who Hear. What a pretty name for a bunch of dreamers who stopped obeying.",
                       "I invented the king's dreams for years. These aren't mine. And that's what frightens me, Caretaker: that for the first time what they dream is true, and the truth asks for something terrible."],
                 opts: ["“Tell them you invented the old dreams.”", "“The circle has to be broken up.”"] },
      verdad: { say: ["And be left without a regency? Without anything holding together three houses that hate each other?",
                      "But she goes down to the hall. Before the circle, her voice breaking, she tells how she wrote the dreams. Many weep. Some leave. Nevisca stays.",
                      "There. Now I'm nothing. If the Heart calls the peoples, the White Deep will go, but not behind me: behind all of you, who asked for it."] },
      disolver: { say: ["At last someone with common sense. Guards.",
                        "The Tomb guard takes the dreamers out one by one. Nevisca, passing you, looks at you with pity.",
                        "You can take us out of the hall. You can't take the dream out of us."] },
      unirte: { say: ["They give you a grey ribbon for your wrist. From that night on, every time you sleep, you hear a little more of the thirst of something very large."] },
    } },
  });

  add("heart", {
    "e2-estatuas": { who: { cincel: "Cincel, sculptor" }, nodes: {
      a: { say: ["Around the Stump, the ground has sunk with the Calm. Where there used to be one moss-covered statue, now four show through, buried at different heights, like steps.",
                 "Forty years I've cleaned the Singer's statue and I never knew she had sisters. Look at the mouths. All four, open in the middle of a note."],
           opts: ["Look at the deepest statue", "Look at the middle one", "Clean the base of the Singer's statue"] },
      honda: { say: ["The deepest has its face erased. Not by time: by blows. Someone went to a lot of trouble so nobody would know who it was.",
                     "That's chisel work. A very old one. A sculptor doesn't erase a face like that. Someone ashamed does."] },
      medio: { say: ["Two of the middle statues are two figures holding hands, one with frost in its hair and one in a mushroom hat. The other has forge slag stuck to its base, as if it turned to stone while working.",
                     "The Nameless Smith. The Ember folk pray to him. They think he's theirs and nobody else's. Look where he is: below the Singer. Before her."] },
      base: { say: ["With a brush and water you clear the moss from the base of the Singer's statue. Underneath are letters, worn but legible. It isn't a verse of any people. It's a single sentence:",
                    "“I will sleep as long as no one drinks beneath my dreams.”",
                    "That isn't in the Song. Nobody sings that.",
                    "Unísona reads the letters with its paw, one by one, and its light goes out for an instant, as when you remember a promise someone else broke."] },
    } },

    "e2-coros": { who: { brezo: "Brezo, keeper of the Stump" }, nodes: {
      a: { say: ["At the edge of the Stump four choirs are camped, each with its banners. The Lantern Houses, the Guild, the White Deep and a group from the Heights. Each rehearses its verse, louder than the one beside it.",
                 "They arrived this week. Each says its verse is the heart of the Song and that, if they sing it alone, the Root will fall fully asleep. They've gone three days without letting each other sleep."],
           opts: ["“What happens if all four sing at once?”", "Ask them to sing together", "Tell them about the statue's base", "Let them rehearse"] },
      vez: { say: ["They did it yesterday, by accident. The ground shook and sap came out of a new crack. Since then they take turns, and insult each other between turns."] },
      juntos: { say: ["You talk with all four. They all listen respectfully: you're the one who calmed the Root. None of them agrees. Each wants to sing first.",
                      "The First Singer told each of them their verse was the heart. It was so they'd look after it. Now it's so they don't listen to each other."] },
      noveno: { say: ["You read them the sentence from the base. There's a long silence, the first in three days.",
                      "“That's a condition,” says a man from the Guild. “It isn't a verse. You don't sing a condition, you keep it.” “Then let the others keep it,” a woman from the Houses replies.",
                      "At least now they know what was broken. Knowing isn't fixing, but it's something."] },
      dejar: { say: ["You walk away among the rehearsals. Four verses, four voices, no lullaby."] },
    } },

    "e2-final": { who: { tila: "Tila", nim: "Nim" }, nodes: {
      a: { say: ["The Wakeful Root won't sleep. You beat it, it fell, it rose again, and it's still down there, eyes open in the dark. Every lullaby sung to it angers it more. The Stump shakes day and night.",
                 "In the middle, Tila and Nim are waiting for you. Unísona stands between them, half dimmed, looking at the base of the statue.",
                 "We have to decide something. We can't wait for it to calm down on its own anymore.",
                 "There are three ways. None of them is good. You choose, it listens to you."],
           opts: ["“What happens if I sing, louder than anyone?”", "“And if we close every well?”", "“And if we sing with only those who are here?”", "Sing louder than anyone and stay in the Heart", "Gather the nine peoples to sing the condition as a promise", "Sing with the peoples who came"] },
      q1: { say: ["The Root sleeps another generation. There'll be a feast in the Ford and they'll make you a beautiful statue. The fifth.",
                  "And you stay here, singing, until your skin turns to stone. Like them. And the wells stay open, and in fifty years, another Caretaker."] },
      q2: { say: ["We have to sing the sentence from the base as a promise, not as a lullaby. With the nine peoples in front, and Unísona as witness.",
                  "The Root doesn't sleep: it stays awake, drinks what's its own and heals for real, very slowly. And we close every well. Every one. The Meadow goes dark.",
                  "And the Houses that lose their last light lose their name. That's their law. You know that, Tila.",
                  "I know."] },
      q3: { say: ["We sing with the peoples you brought. The Root half sleeps, with one eye open.",
                  "Where its people came, the sap settles. Where nobody came, it keeps coming out. A divided Glade: healthy zones and black zones."] },
      quinta: { say: ["You climb the Stump and sing. The eight verses, and Tila's lullaby and Nim's, and the sentence from the base as if it were one more lullaby. You sing louder than all four choirs together.",
                      "The Root falls asleep. The shaking stops. In the Ford, bells begin to ring.",
                      "You can't come down. You don't want to. Your feet are heavy. Tila holds your hand for a long while, until your hand is no longer warm.",
                      "We'll make you a beautiful statue. I promise. And we'll sing to you, so you'll never lack company."] },
      linea: { say: ["The nine arrive. The Houses with Alvar in front, the Fire with its hammer, the Wood in silence, the Heights selling nothing, the Court unveiled, the Tides together, the Hondura with two stones, the White Deep without its regent, and the Dark Quarter, which belongs nowhere and to everyone.",
                     "They don't sing a lullaby. They say the sentence from the base, all at once, looking down: “No one will drink beneath your dreams.” Unísona shines among them all, brighter than ever. It is the witness.",
                     "The Root doesn't fall asleep. It stays awake. It drinks slowly from what's its own. And it stops shaking.",
                     "Now the wells have to be closed. All of them. Starting with my House's, which no longer exists.",
                     "That night, for the first time in thirty years, the Meadow is dark. The stars come out."] },
      ligero: { say: ["The peoples you brought sing, each its verse, one after another, without fighting. You sing the ending. Unísona sings with you.",
                      "The Root grows drowsy. Not completely. The shaking drops to a murmur, like someone sleeping badly.",
                      "Look at the map. Where a people came, the ground is still. Where nobody came, the sap keeps coming out.",
                      "A Glade split in two. At least this time we know where the crack is."] },
    } },
  });
})(window.EVEVENTS_EN);
